/**
 * 我的文档：用户自己导入的 PDF / Word / PPT / EPUB。
 *
 * 一份文档有两半：元数据（书名、类型、大小、创建时间、云端状态）跟着书架走，
 * 正文和原文件（IndexedDB 里的 blob + 抽出来的文字）按需取。书架上那排书脊
 * 只需要元数据，所以列表可以整份读出来；正文可能几兆，永远不整份读。
 *
 * 2026-10-14 起和知识卡、单词本一样按账号分桶（scopedLocalKey）：没登录时
 * 是裸键那份，登录后写进「键::账号 id」，新账号打开是空的。
 */
import type { BookId } from "../components/study/books";
import type { ReaderBook } from "./readerLibrary";

export const DOCUMENTS_STORAGE_KEY = "leafia:documents:v1";
/** 单份文档的正文 + 原文件，键后缀是文档 id。 */
export const DOCUMENT_PAYLOAD_PREFIX = "leafia:document:v1:";
/** 书架 04 那一排最多摆几本。摆满就不再收新的，弹「已满」提示。 */
export const DOCUMENT_ROW_LIMIT = 6;
/** 文档书的 id 前缀，书架和阅读器靠它认出「这是导入的文档」。 */
export const DOCUMENT_BOOK_PREFIX = "doc-";
/** 04 排空着时那本占位书（点它打开导入对话框）。 */
export const DOCUMENT_IMPORT_BOOK_ID = "shelf-04-import-document";

/** 文件选择框收的类型。老格式也列进来，好给出「请另存为」的提示。 */
export const DOCUMENT_ACCEPT = ".pdf,.docx,.pptx,.epub,.doc,.ppt";

export const MODERN_DOCUMENT_EXTENSIONS = [
  "pdf",
  "docx",
  "pptx",
  "epub",
] as const;

export type DocumentCloudStatus = "local" | "uploaded" | "failed";

export interface DocumentCloudState {
  status: DocumentCloudStatus;
  /** 存储桶里的对象路径（user_id/文档 id.后缀）。 */
  path?: string;
  uploadedAt?: string;
  error?: string;
}

export interface ImportedDocument {
  id: string;
  /** 书名（默认取文件名去掉后缀）。 */
  title: string;
  fileName: string;
  /** 大写后缀，PDF / DOCX / PPTX / EPUB。 */
  fileType: string;
  /** 原文件字节数。 */
  size: number;
  createdAt: string;
  /** IndexedDB 里那份 { blob, text } 的键（已按账号分桶）。 */
  storageKey: string;
  cloud: DocumentCloudState;
}

export interface DocumentPayload {
  blob: Blob;
  text: string;
  warnings: string[];
}

export function extensionOf(fileName: string) {
  return fileName.split(".").pop()?.toLowerCase() ?? "";
}

export function documentBookId(id: string) {
  return `${DOCUMENT_BOOK_PREFIX}${id}`;
}

export function isDocumentBookId(id: string) {
  return id.startsWith(DOCUMENT_BOOK_PREFIX);
}

/** 文件名当书名：去掉后缀，压掉多余空白，太长就截断。 */
export function documentTitleFromFileName(fileName: string) {
  const base = fileName.replace(/\.[^.]+$/, "").replace(/\s+/g, " ").trim();
  return (base || fileName).slice(0, 80);
}

/**
 * 收不收这一份文件。老二进制格式（.doc/.ppt）在浏览器里解析不动，
 * 直接给一句能照做的提示，而不是导入完才发现是空页。
 */
export function guardDocumentFile(
  fileName: string,
): { ok: true; extension: string } | { ok: false; message: string } {
  const extension = extensionOf(fileName);
  if ((MODERN_DOCUMENT_EXTENSIONS as readonly string[]).includes(extension)) {
    return { ok: true, extension };
  }
  if (extension === "ppt") {
    return {
      ok: false,
      message: "旧版 .ppt 解析效果差：请在 PowerPoint 里另存为 .pptx 再导入。",
    };
  }
  if (extension === "doc") {
    return {
      ok: false,
      message: "旧版 .doc 解析效果差：请在 Word 里另存为 .docx 再导入。",
    };
  }
  return {
    ok: false,
    message: `暂时只收 PDF / DOCX / PPTX / EPUB，.${
      extension || "未知"
    } 还读不了。`,
  };
}

/** 04 排还剩几个位置；满了就不再收。 */
export function documentRowSpace(count: number) {
  return Math.max(0, DOCUMENT_ROW_LIMIT - count);
}

export function documentRowFull(count: number) {
  return documentRowSpace(count) === 0;
}

export const DOCUMENT_ROW_FULL_MESSAGE = "第四层书架已满，无法继续添加文档";

/** 书脊颜色：按 id 稳定地挑一支，同一份文档永远同一个颜色。 */
const DOCUMENT_SPINES = [
  "#8C6A4F",
  "#6E7F8D",
  "#7D6B8F",
  "#8F7A5A",
  "#5F7F6F",
  "#9A6A72",
];

export function documentSpine(id: string) {
  let hash = 0;
  for (let index = 0; index < id.length; index += 1) {
    hash = (hash * 31 + id.charCodeAt(index)) % 9973;
  }
  return DOCUMENT_SPINES[hash % DOCUMENT_SPINES.length] ?? DOCUMENT_SPINES[0]!;
}

/** 书架上的开本：和原来那排笔记本一个量级，按 id 稳定地错开一点。 */
export function documentDims(id: string) {
  let hash = 0;
  for (let index = 0; index < id.length; index += 1) {
    hash = (hash * 31 + id.charCodeAt(index)) % 997;
  }
  return {
    thickness: 0.226 + (hash % 3) * 0.018,
    height: 0.66 + (hash % 4) * 0.014,
  };
}

function formatSize(size: number) {
  if (size >= 1024 * 1024) return `${(size / 1024 / 1024).toFixed(1)} MB`;
  if (size >= 1024) return `${Math.round(size / 1024)} KB`;
  return `${size} B`;
}

export function documentSizeLabel(doc: Pick<ImportedDocument, "size">) {
  return formatSize(doc.size);
}

export function documentCloudLabel(doc: ImportedDocument) {
  if (doc.cloud.status === "uploaded") return "已备份到云端";
  if (doc.cloud.status === "failed") return "云端备份失败";
  return "只在本机";
}

/**
 * 元数据 → 一本能上书架、能进阅读器的书。
 * 正文不在 ReaderBook 里（`source` 留空）：那种几兆的字符串不进内存，
 * 阅读器按 id 自己去 IndexedDB 取。
 */
export function documentToReaderBook(doc: ImportedDocument): ReaderBook {
  const dims = documentDims(doc.id);
  return {
    id: documentBookId(doc.id) as BookId,
    title: doc.title,
    zhTitle: doc.fileType,
    author: "我的文档",
    spine: documentSpine(doc.id),
    pageTint: "#f7efe2",
    slot: [0, 0],
    coverWidth: 0.18,
    height: dims.height,
    thickness: dims.thickness,
    lean: 0,
    editable: false,
    source: "",
    translation: "",
    custom: true,
    scroll: true,
    documentId: doc.id,
    createdAt: doc.createdAt,
  };
}

/** 04 排空着时立的那本占位书：点它去导入。 */
export function documentImportBook(): ReaderBook {
  return {
    id: DOCUMENT_IMPORT_BOOK_ID as BookId,
    title: "Import a document",
    zhTitle: "导入文档",
    author: "我的文档",
    spine: "#6E7F8D",
    pageTint: "#f4f1ea",
    slot: [0, 0],
    coverWidth: 0.18,
    height: 0.64,
    thickness: 0.2,
    lean: 0,
    editable: false,
    source: "",
    translation: "",
    custom: true,
  };
}
