import { del as idbDel, get as idbGet, set as idbSet } from "idb-keyval";
import { create } from "zustand";
import { scopedLocalKey } from "../lib/accountScope";
import { useAccountStore } from "../lib/auth";
import { createId } from "../lib/createId";
import { extractDocument } from "../lib/documents";
import {
  DOCUMENTS_STORAGE_KEY,
  DOCUMENT_PAYLOAD_PREFIX,
  DOCUMENT_ROW_FULL_MESSAGE,
  documentRowFull,
  documentTitleFromFileName,
  guardDocumentFile,
  type DocumentCloudState,
  type ImportedDocument,
} from "../lib/documentLibrary";

/**
 * 我的文档：导入的文档存在哪、书架 04 那一排摆什么。
 *
 * 元数据（一本一行的清单）和正文分开放：
 *   - 清单         leafia:documents:v1             —— 书架渲染只要它
 *   - 正文文字      leafia:document:v1:<id>:text    —— 阅读器按需取
 *   - 原文件 blob   leafia:document:v1:<id>:blob    —— 云端备份时才读
 * 三份都走 scopedLocalKey 按账号分桶：登录后写「键::账号 id」，没登录是裸键，
 * 和知识卡、单词本一个约定。
 */
interface DocumentsState {
  initialized: boolean;
  /** 现在这一份数据属于谁：null = 没登录时的本机存档。 */
  ownerId: string | null;
  documents: ImportedDocument[];
  hydrate: () => Promise<void>;
  /** 导入一份文件：解析 → 写 IndexedDB → 记元数据。warnings 是解析时的话（如扫描件）。 */
  importFile: (
    file: File,
  ) => Promise<{ doc: ImportedDocument; warnings: string[] }>;
  removeDocument: (id: string) => Promise<void>;
  patchCloud: (id: string, cloud: Partial<DocumentCloudState>) => void;
  readText: (id: string) => Promise<string | null>;
  readBlob: (id: string) => Promise<Blob | null>;
}

function currentOwnerId(): string | null {
  return useAccountStore.getState().session?.user.id ?? null;
}

function textKey(id: string, ownerId: string | null) {
  return scopedLocalKey(`${DOCUMENT_PAYLOAD_PREFIX}${id}:text`, ownerId);
}

function blobKey(id: string, ownerId: string | null) {
  return scopedLocalKey(`${DOCUMENT_PAYLOAD_PREFIX}${id}:blob`, ownerId);
}

function persist(ownerId: string | null, documents: ImportedDocument[]) {
  if (typeof indexedDB === "undefined") return;
  void idbSet(scopedLocalKey(DOCUMENTS_STORAGE_KEY, ownerId), {
    documents,
  }).catch(() => undefined);
}

/** 第几次水合：账号切得快时，先出发的那次回来就作废。 */
let hydrateTicket = 0;

export const useDocuments = create<DocumentsState>((set, get) => ({
  initialized: false,
  ownerId: currentOwnerId(),
  documents: [],

  async hydrate() {
    const ownerId = currentOwnerId();
    if (get().initialized && get().ownerId === ownerId) return;
    const ticket = ++hydrateTicket;
    const stored = await idbGet<{ documents?: ImportedDocument[] }>(
      scopedLocalKey(DOCUMENTS_STORAGE_KEY, ownerId),
    ).catch(() => undefined);
    if (ticket !== hydrateTicket) return;
    set({
      documents: Array.isArray(stored?.documents) ? stored.documents : [],
      ownerId,
      initialized: true,
    });
  },

  async importFile(file) {
    const guard = guardDocumentFile(file.name);
    if (!guard.ok) throw new Error(guard.message);
    if (documentRowFull(get().documents.length)) {
      throw new Error(DOCUMENT_ROW_FULL_MESSAGE);
    }

    // 解析在 IndexedDB 之前做：读不出来的文件不占一个书架位。
    const extracted = await extractDocument(file);
    const ownerId = currentOwnerId();
    const id = createId();

    if (typeof indexedDB !== "undefined") {
      await idbSet(textKey(id, ownerId), extracted.text).catch(() => undefined);
      await idbSet(blobKey(id, ownerId), file).catch(() => undefined);
    }

    const doc: ImportedDocument = {
      id,
      title: documentTitleFromFileName(file.name),
      fileName: file.name,
      fileType: (guard.extension || "document").toUpperCase(),
      size: file.size,
      createdAt: new Date().toISOString(),
      storageKey: textKey(id, ownerId),
      cloud: { status: "local" },
    };
    const documents = [doc, ...get().documents];
    set({ documents });
    persist(ownerId, documents);
    return { doc, warnings: extracted.warnings };
  },

  async removeDocument(id) {
    const ownerId = get().ownerId;
    const documents = get().documents.filter((doc) => doc.id !== id);
    set({ documents });
    persist(ownerId, documents);
    if (typeof indexedDB === "undefined") return;
    await idbDel(textKey(id, ownerId)).catch(() => undefined);
    await idbDel(blobKey(id, ownerId)).catch(() => undefined);
  },

  patchCloud(id, cloud) {
    const ownerId = get().ownerId;
    const documents = get().documents.map((doc) =>
      doc.id === id ? { ...doc, cloud: { ...doc.cloud, ...cloud } } : doc,
    );
    set({ documents });
    persist(ownerId, documents);
  },

  async readText(id) {
    if (typeof indexedDB === "undefined") return null;
    return (
      (await idbGet<string>(textKey(id, get().ownerId)).catch(
        () => undefined,
      )) ?? null
    );
  },

  async readBlob(id) {
    if (typeof indexedDB === "undefined") return null;
    return (
      (await idbGet<Blob>(blobKey(id, get().ownerId)).catch(
        () => undefined,
      )) ?? null
    );
  },
}));

// 登录、退出、换账号：换一份文档清单 —— 新账号打开是空的，
// 退出后回到没登录时那份本机文档。
useAccountStore.subscribe((state, previous) => {
  const next = state.session?.user.id ?? null;
  const before = previous.session?.user.id ?? null;
  if (next === before) return;
  void useDocuments.getState().hydrate();
});
